update pages set contenu = '{"sections":[]}'::jsonb where path = '/implantations/maintenance-industrielle-clermont-ferrand/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Maintenance industrielle à Clermont-Ferrand et dans le Puy-de-Dôme","mecanisme":"Le caoutchouc chauffe, la Limagne travaille en saison, Issoire usine des pièces qui ne tolèrent aucun écart. Trois logiques de production différentes, trois façons d''entretenir un parc. Nous adaptons les gammes et les horaires à chacune, avec des techniciens itinérants qui se déplacent partout en France.","cta":"Demander une intervention à Clermont-Ferrand","telephone":"04 78 33 72 05","phraseDelai":"Un chargé d''affaires vous rappelle dans l''heure, du lundi au vendredi de 8h00 à 18h30. En option, l''astreinte 24/24 et 7/7 couvre les nuits, les week-ends et les jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels en France, dont plus de 80 réguliers"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés avant l''intervention"},{"valeur":"6 semaines","libelle":"de chantier tenues à Clermont-Ferrand pour le montage d''un centre logistique, en 2023"}]},{"type":"probleme","punchline":"Une régulation dérive sur une ligne d''extrusion. Personne ne s''en aperçoit avant la deuxième benne de rebut, et la matière perdue ne se recycle pas toujours.","puces":[{"accroche":"Le caoutchouc pardonne mal l''à-peu-près thermique.","texte":"Presses, mélangeurs, extrudeuses : une consigne qui glisse se paie en qualité avant de se voir en panne."},{"accroche":"La Limagne travaille en fenêtre courte.","texte":"Réception, tri, conditionnement des semences et des céréales : la saison ne se décale pas d''une semaine."},{"accroche":"L''aéronautique et l''outillage exigent la trace écrite.","texte":"Contrôle, traitement thermique, traitement de surface : sans document, l''opération n''existe pas."},{"accroche":"Les sites sont dispersés entre plaine et relief.","texte":"Un prestataire posté dans une seule zone d''activité laisse la moitié du département sans réponse."},{"accroche":"Le technicien qui part emporte l''historique.","texte":"Dans une équipe réduite, un départ suffit à rendre le parc illisible."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Suivi des organes thermiques et de régulation","texte":"sondes, résistances, échangeurs, contrôle par caméra thermique."},"benefice":"La dérive se corrige avant que le rebut ne parte au broyeur."},{"prestation":{"accroche":"Préventif resserré avant la saison","texte":", allégé pendant les creux d''activité."},"benefice":"Vos équipements sont prêts avant le pic, pas réparés pendant."},{"prestation":{"accroche":"Dépannage cadré dès le premier appel","texte":"diagnostic, remise en service, compte rendu écrit."},"benefice":"Un premier chantier suffit à juger la méthode avant tout contrat."},{"prestation":{"accroche":"Couverture multi-technique","texte":"[mécanique](/expertises/mecanique/), [électrique](/expertises/electrique/), [automatisme](/expertises/automatisme/), [hydraulique](/expertises/hydraulique/), [pneumatique](/expertises/pneumatique/), [soudure](/expertises/soudure/)."},"benefice":"Une panne qui croise plusieurs métiers ne réclame pas trois prestataires."},{"prestation":{"accroche":"Traçabilité conforme aux exigences aéronautiques et pharmaceutiques","texte":"opérations documentées, pièces référencées."},"benefice":"Votre qualité retrouve la preuve sans la reconstituer après coup."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7 en option","texte":", mobilisation de techniciens mobiles partout en France."},"benefice":"Un défaut en fin de semaine ne coûte pas le lundi suivant."}],"prose":[{"texte":"Pour les lignes de fabrication et de conditionnement alimentaires, voir la [maintenance en agroalimentaire](/secteurs/agroalimentaire/). Pour les plateformes et les convoyeurs, voir la [maintenance des équipements logistiques](/secteurs/logistique/)."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez le besoin","texte":"machine, symptôme, criticité, accès au site et habilitations exigées."},{"titre":"Nous vous rappelons dans l''heure","texte":"un chargé d''affaires vérifie la compétence disponible et le matériel à prévoir."},{"titre":"Le devis part avant le déplacement","texte":"périmètre, conditions de chantier, chiffrage écrit."},{"titre":"L''intervention suit votre protocole","texte":"accueil sécurité, plan de prévention, consignation, puis diagnostic."},{"titre":"La cause racine passe après la remise en route","texte":"historique machine, mesures, conditions réelles d''exploitation."},{"titre":"Le compte rendu alimente votre GMAO","texte":"constat, actions, pièces, points de vigilance pour le passage suivant."}]},{"type":"garanties","puces":[{"accroche":"Le technicien est évalué, pas seulement recruté","texte":"entretien technique et comportemental, 10 % de candidats retenus, résultats d''évaluation présentés avant l''arrivée sur votre site."},{"accroche":"Aucun délai de route inventé","texte":"rappel dans l''heure aux horaires ouvrés et astreinte 24/24 et 7/7 en option. Le reste dépend de votre localisation exacte et se dit avant d''engager."},{"accroche":"Un cadre écrit du premier au dernier jour","texte":"périmètre, fréquences, indicateurs suivis, conditions de sortie. Le document protège les deux parties."}]},{"type":"cta","question":"Besoin de remettre à plat un parc qui multiplie les arrêts courts ?","bouton":"Demander une intervention à Clermont-Ferrand","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]'::jsonb) where path = '/implantations/maintenance-industrielle-clermont-ferrand/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"12 monteurs mécaniciens et 8 engins de levage pour le montage d''un centre logistique à Clermont-Ferrand","texte":"six semaines de chantier en août 2023, date de livraison tenue","lienLibelle":"Étude de cas AKTID : montage d''un centre logistique","lienHref":"/preuves/aktid-centre-logistique/"},{"titre":"Maintenance préventive et curative d''une fonderie et de son usinage, 7 jours sur 7, depuis octobre 2023","texte":"site de Dompierre-sur-Besbre","lienLibelle":"Étude de cas STELLANTIS : fonderie de Sept-Fons","lienHref":"/preuves/stellantis-fonderie-sept-fons/"},{"titre":"Deux techniciens intégrés en 3x8 sur des lignes liquides et poudre","texte":"nutrition infantile, cadence continue","lienLibelle":"Étude de cas DANONE : lignes de production","lienHref":"/preuves/danone-lignes-de-production/"},{"titre":"Un technicien de maintenance dédié au maintien d''un parc machines en 2025","texte":"poste vacant comblé sans attendre un recrutement","lienLibelle":"Étude de cas AUTOLIV : maintien d''un site","lienHref":"/preuves/autoliv/"},{"titre":"Un technicien polyvalent sur un parc hétérogène en forte cadence","texte":"papier et emballage, 2025 à 2026","lienLibelle":"Étude de cas VPK : maintenance de site","lienHref":"/preuves/vpk/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous vraiment à Clermont-Ferrand, alors que votre siège est à Lyon ?","reponse":"Oui, et nous avons un chantier documenté sur place : le montage du centre logistique AKTID, six semaines en 2023, livré dans les temps. Nos 4 agences sont Lyon (siège), Montréal, Dubaï et Madrid, et nos techniciens se déplacent partout en France. Votre demande est rappelée dans l''heure aux horaires ouvrés. Nous préférons le dire plutôt que d''afficher une adresse locale que personne n''occupe."},{"question":"Quelles communes couvrez-vous dans le département ?","reponse":"Clermont-Ferrand et sa couronne, Aubière, Gerzat, Lempdes, Cournon-d''Auvergne, Riom, la plaine de Limagne, Issoire et Thiers. Au-delà, le relais se fait sur l''Auvergne-Rhône-Alpes puis sur le réseau national."},{"question":"Travaillez-vous sur les presses et les lignes d''extrusion ?","reponse":"Oui : hydraulique de presse, régulation thermique, entraînements, périphériques, organes de sécurité. Le contrôle des dérives de température fait partie du préventif, avec relevés versés dans votre GMAO."},{"question":"Intervenez-vous chez les PME du bassin ou seulement dans les grands groupes ?","reponse":"Les deux. Plus de 120 clients nous font travailler, du groupe national à l''atelier d''une vingtaine de personnes. Le format se dimensionne au besoin : dépannage à l''acte, campagne de travaux, contrat annuel ou technicien intégré."},{"question":"Pouvez-vous tenir un poste que nous n''arrivons pas à recruter ?","reponse":"Oui, avec le [technicien en résidence](/offres/residence/). Un salarié Migen rejoint votre équipe, encadré par un référent technique. Prise de poste en 2 à 3 semaines, remplacement assuré en cas d''absence."},{"question":"Que contient le contrat Zéro arrêt ?","reponse":"Préventif planifié, priorité en cas de panne, astreinte en option. À partir de sur devis, engagement type 6 mois renouvelable. Le périmètre du [contrat de maintenance](/offres/zero-arret/) s''écrit équipement par équipement, après un diagnostic gratuit."}]},{"type":"ctaFinal","question":"Besoin de préparer vos équipements avant la prochaine saison ?","bouton":"Demander une intervention à Clermont-Ferrand","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/implantations/maintenance-industrielle-clermont-ferrand/';
